    I=np.array(I); O=np.array(O); H,W=I.shape
    seeds=[(r,c) for r in range(H) for c in range(W) if I[r][c]==4]
    dist=[[None]*W for _ in range(H)]
    q=deque()
    for s in seeds: dist[s]=(0,None); q.append(s)
    while q:
        y,x=q.popleft(); v=dist[y][x]
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<H and 0<=xx<W and I[yy][xx]!=wall and dist[yy][xx] is None:
